// ?bfmeCheckEQQ@@YGDPAUBfmeUnitEQQ@@@Z
// partial score=0.85 date=2026-09-09
// 86/90 bytes; the FP compare is settled: writing it as `health >= const`
// (not `!(health < const)`) gives retail's exact test ah,1/je form, since
// mask 1 (C0 only) is the >= spelling and mask 5 (C0|C2) is the NaN-safe <.
// Missing 4 bytes: retail retests eax,eax (already known nonzero) before the
// ready-flag load; `if (owner) { if (owner->ready) ... }`, `owner != 0 &&`,
// and `owner == 0 || owner->ready` all fold it away here. Same class as the
// STLport redundant-recheck family in re_attempts.log; not yet solved.
// Pin needed: ?BfmeShareThirdEQQ@@3MB,0x00D1BB98  (float 33.333332)
typedef float Real;

extern const Real BfmeShareThirdEQQ;

struct BfmeOwnerEQQ
{
	unsigned char m_bfmeHeadEQQ[0x41];
	char m_bfmeReadyEQQ;
	char m_bfmeDoneEQQ;
};

struct BfmeBodyEQQ
{
	unsigned char m_bfmeHeadEQQ[0x54];
	Real m_bfmeHealthEQQ;
};

struct BfmeUnitEQQ
{
	unsigned char m_bfmeHeadEQQ[4];
	BfmeBodyEQQ *m_bfmeBodyEQQ;
	unsigned char m_bfmeMidEQQ[4];
	BfmeOwnerEQQ *volatile m_bfmeOwnerEQQ;
	unsigned char m_bfmeTailEQQ[2];
	char m_bfmeFlagAEQQ;
	char m_bfmeFlagBEQQ;
	char m_bfmeFlagCEQQ;
};

char __stdcall bfmeCheckEQQ(BfmeUnitEQQ *unit)
{
	if (!unit->m_bfmeFlagAEQQ && !unit->m_bfmeFlagBEQQ && !unit->m_bfmeFlagCEQQ)
	{
		BfmeBodyEQQ *body = unit->m_bfmeBodyEQQ;
		if (body != 0 && body->m_bfmeHealthEQQ >= BfmeShareThirdEQQ)
			return 0;
		{
			BfmeOwnerEQQ *owner = unit->m_bfmeOwnerEQQ;
			if (owner == 0)
				return 1;
			if (owner != 0 && owner->m_bfmeReadyEQQ)
				return 1;
			BfmeOwnerEQQ *other = unit->m_bfmeOwnerEQQ;
			if (other == 0)
				return 1;
			if (other != 0 && other->m_bfmeDoneEQQ)
				return 1;
		}
	}
	return 0;
}
